// Get data from both HTTP requests
const summary = $('Fetch Daily Summary').first().json;
const lowAttendance = $('Fetch Low Attendance Students').first().json;

// Format date
const today = new Date().toLocaleDateString('en-IN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

// Generate HTML email template
const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      margin: 0;
      padding: 20px;
      background-color: #f5f7fa;
    }
    .container {
      max-width: 700px;
      margin: 0 auto;
      background: white;
      border-radius: 12px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      overflow: hidden;
    }
    .header {
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
      padding: 30px;
      text-align: center;
    }
    .header h1 {
      margin: 0;
      font-size: 24px;
    }
    .header p {
      margin: 10px 0 0;
      opacity: 0.9;
    }
    .content {
      padding: 30px;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 15px;
      margin-bottom: 30px;
    }
    .stat-card {
      background: #f8f9fa;
      border-radius: 8px;
      padding: 20px;
      text-align: center;
    }
    .stat-value {
      font-size: 32px;
      font-weight: bold;
      color: #667eea;
    }
    .stat-label {
      color: #666;
      font-size: 14px;
      margin-top: 5px;
    }
    .section-title {
      color: #333;
      font-size: 18px;
      margin: 25px 0 15px;
      padding-bottom: 10px;
      border-bottom: 2px solid #667eea;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 10px;
    }
    th, td {
      padding: 12px;
      text-align: left;
      border-bottom: 1px solid #eee;
    }
    th {
      background: #667eea;
      color: white;
      font-weight: 600;
    }
    tr:hover {
      background: #f8f9fa;
    }
    .critical {
      background: #fee2e2 !important;
      color: #dc2626;
    }
    .warning {
      background: #fef3c7 !important;
      color: #d97706;
    }
    .footer {
      background: #f8f9fa;
      padding: 20px;
      text-align: center;
      color: #666;
      font-size: 12px;
    }
    .badge {
      display: inline-block;
      padding: 4px 10px;
      border-radius: 20px;
      font-size: 12px;
      font-weight: 600;
    }
    .badge-red { background: #fee2e2; color: #dc2626; }
    .badge-yellow { background: #fef3c7; color: #d97706; }
    .badge-green { background: #d1fae5; color: #059669; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>📊 Daily Attendance Report</h1>
      <p>${today}</p>
    </div>

    <div class="content">
      <div class="stats-grid">
        <div class="stat-card">
          <div class="stat-value">${summary.total_classes || 0}</div>
          <div class="stat-label">Total Classes</div>
        </div>
        <div class="stat-card">
          <div class="stat-value">${summary.average_attendance_rate?.toFixed(1) || 0}%</div>
          <div class="stat-label">Attendance Rate</div>
        </div>
        <div class="stat-card">
          <div class="stat-value" style="color: #059669;">${summary.total_present || 0}</div>
          <div class="stat-label">Present</div>
        </div>
        <div class="stat-card">
          <div class="stat-value" style="color: #dc2626;">${summary.total_absent || 0}</div>
          <div class="stat-label">Absent</div>
        </div>
      </div>

      <h3 class="section-title">⚠️ Students Below ${$env.ALERT_THRESHOLD || 75}% Attendance (${lowAttendance.count || 0})</h3>

      ${lowAttendance.students && lowAttendance.students.length > 0 ? `
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Roll No</th>
            <th>Subject</th>
            <th>Attendance</th>
          </tr>
        </thead>
        <tbody>
          ${lowAttendance.students.slice(0, 20).map(s => {
            const rowClass = s.attendance_percentage < 50 ? 'critical' : s.attendance_percentage < 65 ? 'warning' : '';
            const badgeClass = s.attendance_percentage < 50 ? 'badge-red' : s.attendance_percentage < 65 ? 'badge-yellow' : 'badge-green';
            return `
            <tr class="${rowClass}">
              <td><strong>${s.student_name}</strong></td>
              <td>${s.roll_number}</td>
              <td>${s.subject_name || 'N/A'}</td>
              <td><span class="badge ${badgeClass}">${s.attendance_percentage?.toFixed(1)}%</span></td>
            </tr>
            `;
          }).join('')}
        </tbody>
      </table>
      ${lowAttendance.count > 20 ? `<p style="color: #666; font-size: 14px; margin-top: 10px;">... and ${lowAttendance.count - 20} more students</p>` : ''}
      ` : `<p style="color: #059669;">✅ No students below threshold!</p>`}
    </div>

    <div class="footer">
      <p>Generated by SmartAttend Hub | ${new Date().toISOString()}</p>
      <p>This is an automated report. Do not reply to this email.</p>
    </div>
  </div>
</body>
</html>
`;

// Generate plain text version
const plainText = `
Daily Attendance Report - ${today}

=== Summary ===
Total Classes: ${summary.total_classes || 0}
Attendance Rate: ${summary.average_attendance_rate?.toFixed(1) || 0}%
Present: ${summary.total_present || 0}
Absent: ${summary.total_absent || 0}

=== Low Attendance Students (${lowAttendance.count || 0}) ===
${lowAttendance.students ? lowAttendance.students.slice(0, 10).map(s => 
  `- ${s.student_name} (${s.roll_number}): ${s.attendance_percentage?.toFixed(1)}% in ${s.subject_name}`
).join('\n') : 'No students below threshold'}

---
Generated by SmartAttend Hub
`;

return [{ 
  json: { 
    html, 
    plainText,
    summary,
    lowAttendance,
    date: today,
    subject: `📊 Daily Attendance Report - ${summary.date || today}`
  } 
}];
